1	package wallet
2	
3	import (
4		"errors"
5		"sync"
6		"testing"
7		"time"
8	)
9	
10	// applyPendingForRace 按本文件共用的夹具提交一笔待审批请求：预估费用 20、
11	// 审批门槛 10，出资账户 payer 可用 100，钱包内无其他请求，策略单次与共享
12	// 限额均足够，预留超时关闭。申请会话 s1 属于使用账户 u1，审批会话 sa 属于
13	// 出资账户 payer，设备绑定正确；返回提交时刻与等待截止时刻供后续比对。
14	func applyPendingForRace(t *testing.T, w *Wallet) (createdAt, waitDeadline time.Time) {
15		t.Helper()
16		req, err := w.Apply(approvalApply())
17		if err != nil {
18			t.Fatal(err)
19		}
20		if req.State != RequestPendingApproval {
21			t.Fatalf("state = %v, want pending approval", req.State)
22		}
23		return req.CreatedAt, req.WaitDeadline
24	}
25	
26	// checkTimingKept 断言请求的提交时刻与等待截止时刻保持申请时的值。
27	func checkTimingKept(t *testing.T, got RequestView, createdAt, waitDeadline time.Time) {
28		t.Helper()
29		if !got.CreatedAt.Equal(createdAt) || !got.WaitDeadline.Equal(waitDeadline) {
30			t.Fatalf("timing changed: created %v/%v deadline %v/%v",
31				got.CreatedAt, createdAt, got.WaitDeadline, waitDeadline)
32		}
33	}
34	
35	// checkSessionsAfterRace 断言两项操作结束后申请会话已吊销、审批会话仍有效。
36	func checkSessionsAfterRace(t *testing.T, w *Wallet) {
37		t.Helper()
38		s1, err := w.Session("s1")
39		if err != nil {
40			t.Fatal(err)
41		}
42		if s1.State != SessionRevoked {
43			t.Fatalf("applicant session state = %v, want revoked", s1.State)
44		}
45		sa, err := w.Session("sa")
46		if err != nil {
47			t.Fatal(err)
48		}
49		if sa.State != SessionActive {
50			t.Fatalf("approver session state = %v, want still active", sa.State)
51		}
52	}
53	
54	// checkApproveWonOutcome 校验“批准先成功”的完整结果：请求保持已预留并保留
55	// 批准决定与实际预留时间；出资账户 80 可用 / 20 预留；策略预留 20、已花费 0；
56	// 账本新增一次全额预留与一次零金额批准记录，无吊销拒绝或退款记录。
57	func checkApproveWonOutcome(t *testing.T, w *Wallet, createdAt, waitDeadline, approveAt time.Time) {
58		t.Helper()
59	
60		got, err := w.Request("u1", "r1")
61		if err != nil {
62			t.Fatal(err)
63		}
64		if got.State != RequestReserved {
65			t.Fatalf("state = %v, want reserved after approve-then-revoke", got.State)
66		}
67		if got.ApproverAccountID != "payer" {
68			t.Fatalf("approver = %q, want payer's approval decision kept", got.ApproverAccountID)
69		}
70		if !got.DecidedAt.Equal(approveAt) {
71			t.Fatalf("decided at %v, want approve time %v", got.DecidedAt, approveAt)
72		}
73		if !got.ReservedAt.Equal(approveAt) {
74			t.Fatalf("reserved at %v, want approve time %v", got.ReservedAt, approveAt)
75		}
76		if got.RejectReason != "" {
77			t.Fatalf("reserved request must not carry reject reason: %q", got.RejectReason)
78		}
79		checkTimingKept(t, got, createdAt, waitDeadline)
80	
81		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 80, Reserved: 20}) {
82			t.Fatalf("balance = %+v, want {80 20}; revocation must not release the reservation", bal)
83		}
84		if pv, _ := w.Policy("p-approval"); pv.ReservedTotal != 20 || pv.SpentTotal != 0 {
85			t.Fatalf("policy totals = reserved %d spent %d, want 20/0", pv.ReservedTotal, pv.SpentTotal)
86		}
87	
88		// 账本：申请时的待审批记录之外，恰好新增一次全额预留与一次零金额批准。
89		all := w.Ledger()
90		if len(all) != 3 {
91			t.Fatalf("ledger entries = %d, want 3 (pending + reserve + approval)", len(all))
92		}
93		res, ok := ledgerEntryFor(all, LedgerReserve, "r1")
94		if !ok {
95			t.Fatal("missing LedgerReserve entry")
96		}
97		if res.AccountID != "payer" || res.Amount != 20 || !res.At.Equal(approveAt) {
98			t.Fatalf("reserve entry = %+v, want payer full-amount 20 at approve time", res)
99		}
100		app, ok := ledgerEntryFor(all, LedgerApproval, "r1")
101		if !ok {
102			t.Fatal("missing LedgerApproval entry")
103		}
104		if app.AccountID != "u1" || app.Amount != 0 || !app.At.Equal(approveAt) {
105			t.Fatalf("approval entry = %+v, want zero-amount entry for u1 at approve time", app)
106		}
107		if n := countKind(all, LedgerRejection); n != 0 {
108			t.Fatalf("rejection entries = %d, want none: approved request must not be revoked-rejected", n)
109		}
110		if n := countKind(all, LedgerRefund); n != 0 {
111			t.Fatalf("refund entries = %d, want none: revocation must not refund the reservation", n)
112		}
113	}
114	
115	// checkRevokeWonOutcome 校验“吊销先完成”的完整结果：请求进入拒绝终态，理由
116	// 说明申请会话已被吊销，决定时间为吊销时刻，审批账户为空；出资账户 100 可用 /
117	// 0 预留；策略预留与已花费均为 0；账本只新增一次零金额拒绝记录。
118	func checkRevokeWonOutcome(t *testing.T, w *Wallet, createdAt, waitDeadline, revokeAt time.Time) {
119		t.Helper()
120	
121		got, err := w.Request("u1", "r1")
122		if err != nil {
123			t.Fatal(err)
124		}
125		if got.State != RequestRejected {
126			t.Fatalf("state = %v, want rejected after revoke-then-approve", got.State)
127		}
128		if got.RejectReason != sessionRevokedRejectReason {
129			t.Fatalf("reject reason = %q, want %q", got.RejectReason, sessionRevokedRejectReason)
130		}
131		if !got.DecidedAt.Equal(revokeAt) {
132			t.Fatalf("decided at %v, want revoke time %v", got.DecidedAt, revokeAt)
133		}
134		if got.ApproverAccountID != "" {
135			t.Fatalf("revocation rejection must not fill approver, got %q", got.ApproverAccountID)
136		}
137		if !got.ReservedAt.IsZero() {
138			t.Fatalf("rejected request must never have been reserved, reserved at %v", got.ReservedAt)
139		}
140		checkTimingKept(t, got, createdAt, waitDeadline)
141	
142		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
143			t.Fatalf("balance = %+v, want {100 0}; rejected request must not freeze funds", bal)
144		}
145		if pv, _ := w.Policy("p-approval"); pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
146			t.Fatalf("policy totals = reserved %d spent %d, want 0/0", pv.ReservedTotal, pv.SpentTotal)
147		}
148	
149		// 账本：申请时的待审批记录之外，只新增一次零金额拒绝记录。
150		all := w.Ledger()
151		if len(all) != 2 {
152			t.Fatalf("ledger entries = %d, want 2 (pending + rejection)", len(all))
153		}
154		rej, ok := ledgerEntryFor(all, LedgerRejection, "r1")
155		if !ok {
