164			}
165		}
166	}
167	
168	// TestApproveThenRevokeKeepsReservation：批准先成功时请求保持已预留，随后的
169	// 吊销只改变申请会话状态，不释放已预留费用、不追加拒绝或退款记录。
170	func TestApproveThenRevokeKeepsReservation(t *testing.T) {
171		w, c := setupApproval(t)
172		createdAt, waitDeadline := applyPendingForRace(t, w)
173	
174		// 未到会话到期、未到等待期限、策略在授权时间窗内时批准。
175		c.t = c.t.Add(10 * time.Second)
