193	// TestRevokeThenApproveRejected：吊销先完成时请求进入拒绝终态；随后用仍然
194	// 有效的出资账户会话批准，返回请求不处于待审批状态错误，且不改变任何结果。
195	func TestRevokeThenApproveRejected(t *testing.T) {
196		w, c := setupApproval(t)
197		createdAt, waitDeadline := applyPendingForRace(t, w)
198	
199		c.t = c.t.Add(10 * time.Second)
200		revokeAt := c.t
201		if err := w.RevokeSession("s1"); err != nil {
202			t.Fatal(err)
203		}
204		checkSessionsAfterRace(t, w)
205		checkRevokeWonOutcome(t, w, createdAt, waitDeadline, revokeAt)
206	
207		// 出资账户的审批会话始终有效：不能把申请会话被吊销误当成审批人无权
208		// 操作，错误必须是请求不处于待审批状态，而不是无权审批。
209		before := len(w.Ledger())
210		_, approveErr := w.Approve("u1", "r1", "sa", "dev-approve")
211		if !errors.Is(approveErr, ErrRequestNotPending) {
212			t.Fatalf("approve after revocation err = %v, want ErrRequestNotPending", approveErr)
213		}
214		if errors.Is(approveErr, ErrNotApprover) {
215			t.Fatal("approver session is still valid; must not report ErrNotApprover")
216		}
217		if len(w.Ledger()) != before {
218			t.Fatalf("failed approve grew ledger %d -> %d", before, len(w.Ledger()))
219		}
220		// 失败的批准不改变任何已结清的结果。
221		checkRevokeWonOutcome(t, w, createdAt, waitDeadline, revokeAt)
222	}
223	
224	// TestConcurrentRevokeAndApprove：吊销与批准同时竞争同一笔待审批请求时，
225	// 只能出现“批准先成功”或“吊销先完成”其中一种完整结果；两项调用结束后申请
226	// 会话均已吊销，请求提交时间与等待截止时间不变，调用结果、请求查询、余额、
227	// 策略金额与账本彼此一致。
228	func TestConcurrentRevokeAndApprove(t *testing.T) {
229		const iterations = 32
230		outcomes := map[string]int{}
231		for i := 0; i < iterations; i++ {
232			w, c := setupApproval(t)
233			createdAt, waitDeadline := applyPendingForRace(t, w)
234			c.t = c.t.Add(10 * time.Second)
235			opAt := c.t
236	
237			start := make(chan struct{})
238			var wg sync.WaitGroup
239			var approveErr error
240			wg.Add(2)
241			go func() {
242				defer wg.Done()
243				<-start
244				_, approveErr = w.Approve("u1", "r1", "sa", "dev-approve")
245			}()
246			var revokeErr error
247			go func() {
248				defer wg.Done()
249				<-start
250				revokeErr = w.RevokeSession("s1")
251			}()
252			close(start)
253			wg.Wait()
254	
255			// 吊销本身总是成功；无论哪种结果，申请会话都已吊销、审批会话仍有效。
256			if revokeErr != nil {
257				t.Fatalf("iter %d: revoke err = %v", i, revokeErr)
258			}
259			checkSessionsAfterRace(t, w)
260	
261			switch {
262			case approveErr == nil:
263				// 批准先成功：吊销只改变会话状态，预留完整保留。
264				outcomes["approve-first"]++
265				checkApproveWonOutcome(t, w, createdAt, waitDeadline, opAt)
266			case errors.Is(approveErr, ErrRequestNotPending):
267				// 吊销先完成：请求已拒绝，批准按非待审批失败。
268				outcomes["revoke-first"]++
269				checkRevokeWonOutcome(t, w, createdAt, waitDeadline, opAt)
270			default:
271				t.Fatalf("iter %d: approve err = %v, want nil or ErrRequestNotPending", i, approveErr)
272			}
273		}
274		t.Logf("outcomes: %v", outcomes)
275	}
