325	func TestApplyIdempotencyAndConflict(t *testing.T) {
326		w, _ := setupApply(t)
327		in := baseApply()
328		first, err := w.Apply(in)
329		if err != nil {
330			t.Fatal(err)
331		}
332		second, err := w.Apply(in)
333		if err != nil {
334			t.Fatalf("idempotent re-apply: %v", err)
335		}
336		if second.RequestID != first.RequestID || second.State != first.State || second.EstimatedFee != first.EstimatedFee {
337			t.Fatalf("idempotent result differs: %+v vs %+v", first, second)
338		}
339		bal, _ := w.Balance("payer")
340		if bal != (Balances{Available: 80, Reserved: 20}) {
341			t.Fatalf("double reservation on idempotent re-apply: %+v", bal)
342		}
343	
344		for _, mutate := range []func(*RequestInput){
345			func(x *RequestInput) { x.PolicyID = "other" },
346			func(x *RequestInput) { x.Operation = "refund" },
347			func(x *RequestInput) { x.Payee = "other-shop" },
348			func(x *RequestInput) { x.EstimatedFee = 19 },
349		} {
350			conflict := in
351			mutate(&conflict)
