func TestConcurrentAppliesSettlesCancels(t *testing.T) {
	w, c := setupApply(t)
	// 额度 50：仅能容纳两笔（20+20），并发下不能超扣。
	const n = 8
	var wg sync.WaitGroup
	errs := make([]error, n)
	wg.Add(n)
	for i := 0; i < n; i++ {
